function who() {
  return this === undefined ? "nobody" : this.name;
}

const robot = {
  name: "Bolt",
  who,
  ask() {
    return who();
  },
  askSelf() {
    return this.who();
  },
};

console.log(who());
console.log(robot.who());
console.log(robot.ask());
console.log(robot.askSelf());
